def partition(s):
    result = []
    path = []

    def is_palindrome(sub):
        return sub == sub[::-1]

    def backtrack(start):
        if start == len(s):
            result.append(path[:])
            return
        for end in range(start + 1, len(s) + 1):
            candidate = s[start:end]
            if is_palindrome(candidate):                             # rechecked from scratch every single time
                path.append(candidate)
                backtrack(end)
                path.pop()

    backtrack(0)
    return result


if __name__ == "__main__":
    s = "aab"
    print(partition(s))

