import java.util.*;

public class Main {
    List<List<String>> partition(String s) {
        List<List<String>> result = new ArrayList<>();
        backtrack(s, 0, new ArrayList<>(), result);
        return result;
    }

    void backtrack(String s, int start, List<String> path, List<List<String>> result) {
        if (start == s.length()) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int end = start + 1; end <= s.length(); end++) {
            String candidate = s.substring(start, end);
            if (isPalindrome(candidate)) {                                  // rechecked from scratch every single time
                path.add(candidate);
                backtrack(s, end, path, result);
                path.remove(path.size() - 1);
            }
        }
    }

    boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) return false;
            left++; right--;
        }
        return true;
    }

    public static void main(String[] args) {
        String s = "aab";
        Main solution = new Main();
        System.out.println(solution.partition(s));
    }
}

