def partition(s):
    n = len(s)
    is_palin = [[False] * n for _ in range(n)]
    for i in range(n):
        is_palin[i][i] = True
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and (length == 2 or is_palin[i + 1][j - 1]):
                is_palin[i][j] = True                                     # built from a smaller already known result

    result = []
    path = []

    def backtrack(start):
        if start == n:
            result.append(path[:])
            return
        for end in range(start, n):
            if is_palin[start][end]:                                       # instant lookup, no rescanning
                path.append(s[start:end + 1])
                backtrack(end + 1)
                path.pop()

    backtrack(0)
    return result


if __name__ == "__main__":
    s = "aab"
    print(partition(s))

