import java.util.*;

public class Main {
    List<List<String>> partition(String s) {
        int n = s.length();
        boolean[][] isPalin = new boolean[n][n];
        for (int i = 0; i < n; i++) isPalin[i][i] = true;
        for (int length = 2; length <= n; length++) {
            for (int i = 0; i + length - 1 < n; i++) {
                int j = i + length - 1;
                if (s.charAt(i) == s.charAt(j) && (length == 2 || isPalin[i + 1][j - 1])) {
                    isPalin[i][j] = true;                                        // built from a smaller known result
                }
            }
        }
        List<List<String>> result = new ArrayList<>();
        backtrack(s, 0, isPalin, new ArrayList<>(), result);
        return result;
    }

    void backtrack(String s, int start, boolean[][] isPalin, List<String> path, List<List<String>> result) {
        if (start == s.length()) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int end = start; end < s.length(); end++) {
            if (isPalin[start][end]) {                                             // instant lookup, no rescanning
                path.add(s.substring(start, end + 1));
                backtrack(s, end + 1, isPalin, path, result);
                path.remove(path.size() - 1);
            }
        }
    }

    public static void main(String[] args) {
        String s = "aab";
        Main solution = new Main();
        System.out.println(solution.partition(s));
